SELECT , conversation_group."name" AS "conversation_group_name" FROM "conversation" c LEFT JOIN "conversation_group" conversation_group ON conversation_group."creator_id" = c."creator_id" AND conversation_group."id" = c."conversation_group_id" WHERE c."creator_id" = #{userId} AND c."deleted" = FALSE
AND c."conversation_group_id" = #{conversationGroupId}
AND c."conversation_group_id" IS NULL
AND c."title" ILIKE CONCAT('%', #{keyword}, '%')
ORDER BY CASE WHEN c."conversation_group_id" IS NULL THEN c."pinned" ELSE FALSE END DESC, c."last_round_updated_time" DESC, c."id" DESC LIMIT #{limit} OFFSET #{offset}

